/**
 * A Command (spec/events.md). For `Label`, `project` of `None` leaves the project untouched
 * and an empty string clears it; `label` of `None` clears the label.
 */

public enum CoreCommand: Equatable, Hashable {
    
    case start(kind: CoreKind, plannedMs: Int64, label: String?, project: String?
    )
    case pause
    case resume
    case extend(addMs: Int64
    )
    case skip
    case stop
    case reset
    case label(blockId: String?, label: String?, project: String?
    )





}

#if compiler(>=6)
extension CoreCommand: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreCommand: FfiConverterRustBuffer {
    typealias SwiftType = CoreCommand

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreCommand {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .start(kind: try FfiConverterTypeCoreKind.read(from: &buf), plannedMs: try FfiConverterInt64.read(from: &buf), label: try FfiConverterOptionString.read(from: &buf), project: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 2: return .pause
        
        case 3: return .resume
        
        case 4: return .extend(addMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 5: return .skip
        
        case 6: return .stop
        
        case 7: return .reset
        
        case 8: return .label(blockId: try FfiConverterOptionString.read(from: &buf), label: try FfiConverterOptionString.read(from: &buf), project: try FfiConverterOptionString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreCommand, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .start(kind,plannedMs,label,project):
            writeInt(&buf, Int32(1))
            FfiConverterTypeCoreKind.write(kind, into: &buf)
            FfiConverterInt64.write(plannedMs, into: &buf)
            FfiConverterOptionString.write(label, into: &buf)
            FfiConverterOptionString.write(project, into: &buf)
            
        
        case .pause:
            writeInt(&buf, Int32(2))
        
        
        case .resume:
            writeInt(&buf, Int32(3))
        
        
        case let .extend(addMs):
            writeInt(&buf, Int32(4))
            FfiConverterInt64.write(addMs, into: &buf)
            
        
        case .skip:
            writeInt(&buf, Int32(5))
        
        
        case .stop:
            writeInt(&buf, Int32(6))
        
        
        case .reset:
            writeInt(&buf, Int32(7))
        
        
        case let .label(blockId,label,project):
            writeInt(&buf, Int32(8))
            FfiConverterOptionString.write(blockId, into: &buf)
            FfiConverterOptionString.write(label, into: &buf)
            FfiConverterOptionString.write(project, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreCommand_lift(_ buf: RustBuffer) throws -> CoreCommand {
    return try FfiConverterTypeCoreCommand.lift(buf)
}

