@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreCommand_lower(_ value: CoreCommand) -> RustBuffer {
    return FfiConverterTypeCoreCommand.lower(value)
}



public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A bad argument (non-positive duration, malformed source, ...).
     */
    case InvalidArgument(message: String
    )
    /**
     * The command is not valid for the current Timer state.
     */
    case InvalidState(message: String
    )
    case NotFound(message: String
    )
    case BadTicket(message: String
    )
    /**
     * The other Device refused the pairing (bad secret, expired, used).
     */
    case PairingRejected(message: String
    )
    /**
     * Network or protocol failure during pairing or sync.
     */
    case Sync(message: String
    )
    /**
     * Storage failure or other internal error.
     */
    case Internal(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidState(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .BadTicket(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .PairingRejected(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Sync(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidState(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NotFound(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .BadTicket(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .PairingRejected(message):
            writeInt(&buf, Int32(5))
